function gfxGround(dt){ if(!gfxHook('ground')) return false; try{ gfxPuddles(dt); }catch(_gpd){} return true; }   // D: ground stamps, puddles, casings
// v23.xx (gfx28), HIS ORDER (2026-10-12) on the graphics program: "add ALL of this stuff", item 12, richer ground. PUDDLES, AND THE
// LAMPS IN THEM. When the ground is wet (gfx27), standing water shows: puddles on the open ground of COLD STORAGE, and every lamp
// within 260 units of one throws a streak of its own colour across it, flickering with the lamp. The sites are fixed for the map
// (a hash of a 200-unit grid, about one cell in four; never under a roof, in the water or on a wall), worked out once a raid the
// first time the ground is drawn, so you learn where the water lies. Four baked puddle shapes, drawn only on screen and at the
// strength of the wetness: on a dry raid nothing is drawn at all. COLD STORAGE only (the per-map work of the program); render
// only, no seeded draw, nothing in a bot raid.
var PUDSPR=gfxStore('pud');
function gfxPudSprite(v){
  var s=PUDSPR.m['p'+v], c, i, a, rx, ry;
  if(s) return s;
  s=document.createElement('canvas'); s.width=144; s.height=88; c=s.getContext('2d');
  c.scale(2,2); c.translate(36,22);
  c.fillStyle='rgba(16,22,30,.50)';
  for(i=0;i<4;i++){
    a=grit(v*97+i*13,v*31+i*7)*6.2832; rx=11+grit(v*7+i,v*11+i*3)*12; ry=rx*(0.42+grit(v*5+i*9,v*3+i)*0.2);
    c.beginPath(); c.ellipse(Math.cos(a)*9,Math.sin(a)*4.5,rx,ry,0,0,6.2832); c.fill();
  }
  c.globalCompositeOperation='source-atop';
  c.fillStyle='rgba(150,172,196,.16)'; c.beginPath(); c.ellipse(-4,-3,16,5,0,0,6.2832); c.fill();
  c.fillStyle='rgba(6,9,14,.22)'; c.beginPath(); c.ellipse(5,4,20,6,0,0,6.2832); c.fill();
  PUDSPR.m['p'+v]=s; PUDSPR.n++;
  return s;
}
function gfxPudSites(map){
  var out=[], cs=200, cx, cy, x, y, i, L2, d;
  if(!map||map.fixed!=='cold') return out;
  for(cy=0;cy<WORLD_H;cy+=cs) for(cx=0;cx<WORLD_W;cx+=cs){
    if(grit(cx+17,cy+29)>0.26) continue;
    x=cx+36+grit(cx+5,cy+3)*(cs-72); y=cy+36+grit(cx+11,cy+7)*(cs-72);
    if(x<90||y<90||x>WORLD_W-90||y>WORLD_H-90) continue;
    if(roofAt(x,y)||(typeof inWaterMap==='function'&&inWaterMap(map,x,y))||!spotFree(map,x,y,40)) continue;
    out.push({x:x,y:y,v:Math.floor(grit(cx+3,cy+41)*4),k:0.8+grit(cx+23,cy+19)*0.5,lamps:[]});
  }
  for(i=0;i<out.length;i++) for(var j=0;j<(G.lights||[]).length;j++){
    L2=G.lights[j]; d=Math.hypot(L2.x-out[i].x,L2.y-out[i].y);
    if(d<260) out[i].lamps.push({L:L2,d:d});
  }
  return out;
}
function gfxPuddles(dt){
  var k=gfxWet(), P, i, j, q, s, Z, ox, oy, VW, VH, n=0, ns=0, lk, L2, fk, day, dx, sw;
  GFX.pudN=0; GFX.pudS=0;
  if(!G||G.sim||!G.map) return 0;
  if(G.gfxPudG!==G.map){ G.gfxPud=gfxPudSites(G.map); G.gfxPudG=G.map; }
  P=G.gfxPud;
  if(!(k>0.02)||!P||!P.length) return 0;
  Z=ZOOM(); ox=VX; oy=VY; VW=W/Z; VH=H/Z; day=isDay();
  wc.save();
  try{
    for(i=0;i<P.length;i++){
      q=P[i];
      if(q.x<ox-60||q.x>ox+VW+60||q.y<oy-40||q.y>oy+VH+40) continue;
      s=gfxPudSprite(q.v);
      wc.globalCompositeOperation='source-over'; wc.globalAlpha=Math.min(1,k*0.9);
      wc.drawImage(s,q.x-36*q.k,q.y-22*q.k,72*q.k,44*q.k);
      n++;
      if(!q.lamps.length) continue;
      wc.globalCompositeOperation='lighter';
      for(j=0;j<q.lamps.length;j++){
        lk=q.lamps[j]; L2=lk.L;
        fk=(L2.fl?(.72+.28*Math.sin(G.t*11+L2.f)):1)*wx().lights*(day?tod().lights:1);
        if(fk<=0.02) continue;
        dx=Math.max(-14,Math.min(14,(L2.x-q.x)*0.12))*q.k; sw=(day?0.18:0.42)*k*fk*(1-lk.d/260);
        wc.globalAlpha=Math.min(1,sw); wc.fillStyle=L2.c;
        wc.beginPath(); wc.ellipse(q.x+dx,q.y+1,2.4*q.k,10*q.k,0,0,6.2832); wc.fill();
        wc.globalAlpha=Math.min(1,sw*0.5);
        wc.beginPath(); wc.ellipse(q.x+dx,q.y+1,5*q.k,15*q.k,0,0,6.2832); wc.fill();
        ns++;
      }
    }
  } finally { wc.restore(); }
  GFX.pudN=n; GFX.pudS=ns;
  return n;
}

